mapper.select:
        SELECT COUNT(DISTINCT user_id) AS chat_user_count
        FROM (

                 SELECT user_sender_id AS user_id
                 FROM chat
                 WHERE DATE(create_time) = #{date}

                 UNION


                 SELECT user_receiver_id AS user_id
                 FROM chat
                 WHERE DATE(create_time) = #{date}
             ) AS all_users
